     5	
     6	/**
     7	 * Sends e-mails to guests, after the rules in force have had their say. Every message, sent or blocked, is kept in
     8	 * the list of sent messages.
     9	 */
    10	public final class EmailSender {
    11	
    12	    private final SentMessages sentMessages;
    13	    private final List<ScopedRule> rules;
    14	    private final boolean testMode;
    15	
    16	    public EmailSender(SentMessages sentMessages, List<ScopedRule> rules, boolean testMode) {
    17	        this.sentMessages = sentMessages;
    18	        this.rules = rules;
    19	        this.testMode = testMode;
    20	    }
    21	
    22	    /** Returns the message itself; the copies the rules added are kept right after it. */
    23	    public Message send(String to, String subject, String body) {
    24	        List<OutgoingMessage> outgoing = List.of(new OutgoingMessage(to, subject, body));
    25	        for (ScopedRule scoped : rules) {
    26	            if (scoped.scope().covers(testMode)) {
    27	                outgoing = outgoing.stream()
    28	                        .flatMap(message -> message.isBlocked() ? Stream.of(message) : scoped.rule().apply(message).stream())
    29	                        .toList();
    30	            }
    31	        }
    32	        List<Message> kept = outgoing.stream().map(message -> sentMessages.add("EMAIL", message)).toList();
    33	        return kept.get(0);
    34	    }
    35	}
